mapper.select:
SELECT COUNT(1)
FROM merchant_improvement_record mir
WHERE mir.merchant_id = #{merchantId}

    AND mir.dish_id = #{dishId}


    AND mir.feedback_id = #{feedbackId}


    AND mir.status = #{status}

SELECT mir.id, mir.dish_id AS dishId, d.name AS dishName, mir.feedback_id AS feedbackId, f.content AS feedbackContent, mir.title, mir.content, mir.before_description AS beforeDescription, mir.after_description AS afterDescription, mir.status, mir.is_public AS isPublic, mir.created_at AS createdAt FROM merchant_improvement_record mir LEFT JOIN dish d ON d.id = mir.dish_id LEFT JOIN feedback f ON f.id = mir.feedback_id WHERE mir.merchant_id = #{merchantId}
AND mir.dish_id = #{dishId}
AND mir.feedback_id = #{feedbackId}
AND mir.status = #{status}
ORDER BY mir.created_at DESC, mir.id DESC LIMIT #{offset}, #{size}
